function findProduct(id) {
  return PRODUCTS.find(function (p) { return p.id === id; });
}

function formatPrice(n) {
  if (n === null || n === undefined || n === "") return "";
  return Number(n).toLocaleString("en-US");
}

function priceHTML(p) {
  if (p.price === null || p.price === undefined || p.price === "") return "";
  var current = (p.priceFrom ? "ابتداءً من " : "") + formatPrice(p.price) + " " + p.unit;
  if (p.originalPrice) {
    return (
      current +
      ' <span class="line-through text-on-surface-variant font-normal text-[0.7em] align-middle">' +
      formatPrice(p.originalPrice) + " " + p.unit +
      "</span>"
    );
  }
  return current;
}